gog(){return"\uc2dc\uc791\uc744 \ub204\ub97c \ub54c\ub9c8\ub2e4 \ub2e4\ub978 \uc2dc\ub4dc \ubcf4\ub4dc\uac00 \uc0dd\uc131\ub429\ub2c8\ub2e4. \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uace0 \uc7ac\uac1c\ud558\uba74 \ud574\ub2f9 \ubcf4\ub4dc\ub97c \uc720\uc9c0\ud569\ub2c8\ub2e4."},
gof(){return"\uc721\uac01\ud615 \ubcf4\ub4dc\ub294 \uc138 \uac1c\uc758 \ucd95\uacfc \uc601\uc5ed\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \ud640\uc218 \ubc0f \uc9dd\uc218 \ub2e8\uacc4\ub294 \ubc29\ud5a5\uc744 \ubc88\uac08\uc544 \uac00\uba70 \ub098\ud0c0\ub0a9\ub2c8\ub2e4."},
goC(){return"100\uac1c\uc758 \uace0\uc815 \uc2a4\ud14c\uc774\uc9c0\ub85c \uaca8\ub8e8\ub294 \ube44\ub3d9\uae30\uc2dd \uac1c\uc778 \ub7ad\ud0b9. \ucd1d \uc2dc\uac04\uc5d0\ub294 \ubaa8\ub4e0 \uc2a4\ud14c\uc774\uc9c0\uc640 \uc7ac\ub3c4\uc804 \uc2dc\uac04\uc774 \ud3ec\ud568\ub429\ub2c8\ub2e4."},
