gom(){return"\uc77c\uc77c \ub3c4\uc804\uc744 \uc644\ub8cc\ud560 \ub54c\ub9c8\ub2e4 \ubb34\ub8cc\uc640 Premium \ubaa8\ub450 \ud78c\ud2b8 1\uac1c\ub97c \ubc1b\uc2b5\ub2c8\ub2e4. \uc774\ubca4\ud2b8 \ubcf4\uc0c1\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4."},
gob(){return"\ubcf4\uc0c1\ud615 \uad11\uace0\ub294 \ud78c\ud2b8 1\uac1c\ub97c \ubd80\uc5ec\ud569\ub2c8\ub2e4. \ud78c\ud2b8 \ubc0f \ub2f5\ubcc0 \uc778\ubca4\ud1a0\ub9ac\ub294 \uc804\uc5ed\uc801\uc774\uba70 \uac01\uac01 \ucd5c\ub300 9\uac1c\ub85c \uc81c\ud55c\ub429\ub2c8\ub2e4."},
gou(){return"Premium\uc740 \uc77c\ubc18 \uad11\uace0\ub97c \uc601\uad6c\uc801\uc73c\ub85c \uc81c\uac70\ud558\uace0 \uae30\ub2a5\uc744 \uc7a0\uae08 \ud574\uc81c\ud569\ub2c8\ub2e4. \uc77c\uc77c \ub3c4\uc804 \ucd94\uac00 \ud69f\uc218\uc5d0\ub294 \uc120\ud0dd\uc801\uc778 \ubcf4\uc0c1 \uad11\uace0 \uc2dc\uccad\uc774 \ud544\uc694\ud569\ub2c8\ub2e4."},
goB(){return"\uc791\uc740 \ub3d9\uc601\uc0c1 \ubc30\uc9c0\ub294 \ubb34\ub8cc \ubc84\uc804\uc5d0\uc11c \uacc4\uc18d\ud558\uae30 \uc804\uc5d0 \ubcf4\uc0c1\ud615 \uad11\uace0\ub97c \uc644\ub8cc\ud574\uc57c \ud568\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4."},
gox(){return"\uac8c\uc784 \uc124\uc815\uc740 \uacc4\uc815, \ud50c\ub808\uc774\uc5b4 \uc2e0\uc6d0, \uc544\ubc14\ud0c0, \uc5b8\uc5b4, \uc74c\uc545, \uc0ac\uc6b4\ub4dc \ubc0f \uc9c4\ud589 \uc0c1\ud669\uc744 \uad00\ub9ac\ud569\ub2c8\ub2e4."},
goe(){return"\uc560\uc644\ub3d9\ubb3c \uc9c0\uc6d0\uc740 \ub2f5\ubcc0 1\uac1c\ub97c \uc18c\ube44\ud558\uc5ec \ub2e4\uc74c \uc62c\ubc14\ub978 \uc560\uc644\ub3d9\ubb3c\uc744 \ubc30\uce58\ud569\ub2c8\ub2e4. \ud78c\ud2b8\ub294 \ud558\ub098\uc758 \uc720\ud6a8\ud55c \ub17c\ub9ac\uc801 \ub2e8\uacc4\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4."},
